import { Injectable } from '@nestjs/common';

@Injectable()
export class NotificationService {
  kirim(event: string, data: unknown) {
    // Di produksi: email/SMS/push. Di sini cukup console.
    console.log(`[NOTIF] ${event}:`, data);
  }
}
